<?php
require __DIR__ . '/includes/bootstrap.php'; require_login(); no_cache();
$pageTitle='Vaccination registration'; $errors=[]; $values=[];
if (request_is_post()) {
    if (!verify_csrf()) $errors['_form']='Your form session expired. Refresh the page and try again.';
    $values=array_map(static fn($v)=>is_string($v)?trim($v):'',$_POST);
    foreach (['full_name'=>'Full name','age'=>'Age','city'=>'City','phone'=>'Phone','vaccination_status'=>'Vaccination status','vaccine_or_dose'=>'Vaccine or dose'] as $field=>$label) { $e=validate_field($field,$values[$field]??null); if($e)$errors[$field]=$e; }
    if (!$errors) {
      $db=db_or_error(); if(!$db)$errors['_form']='Could not save your record. Check the database connection.';
      else { $q=$db->prepare('INSERT INTO vaccination_registrations (user_id,full_name,age,city,contact_phone,vaccination_status,vaccine_or_dose) VALUES (:user_id,:full_name,:age,:city,:phone,:status,:dose)'); try {$q->execute(['user_id'=>current_user()['id'],'full_name'=>$values['full_name'],'age'=>(int)$values['age'],'city'=>$values['city'],'phone'=>$values['phone'],'status'=>$values['vaccination_status'],'dose'=>$values['vaccine_or_dose']]);flash('success','Your demonstration record was saved. This is not a vaccination appointment.');redirect('vaccination.php');}catch(Throwable $e){error_log('Vaccination registration failed: '.$e->getMessage());$errors['_form']='The record could not be saved. Please try again.';} }
    }
}
$db=db_or_error(); $mine=[]; if($db){$q=$db->prepare('SELECT full_name,age,city,vaccination_status,vaccine_or_dose,created_at FROM vaccination_registrations WHERE user_id=:id ORDER BY created_at DESC');$q->execute(['id'=>current_user()['id']]);$mine=$q->fetchAll();}
require __DIR__ . '/includes/header.php';
